CREATE TABLE guests (
 id BIGINT PRIMARY KEY AUTO_INCREMENT,
 name VARCHAR(100) NOT NULL,
 phone VARCHAR(30) NOT NULL DEFAULT '',
 attending VARCHAR(10) NOT NULL,
 `count` INT NOT NULL,
 wish TEXT NOT NULL,
 approved TINYINT NOT NULL DEFAULT 0,
 kind VARCHAR(20) NOT NULL DEFAULT 'rsvp',
 side VARCHAR(20) NOT NULL DEFAULT '',
 event VARCHAR(100) NOT NULL DEFAULT '',
 message TEXT NOT NULL,
 submission_key VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin UNIQUE,
 payload_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
 created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 INDEX guests_hash_created(payload_hash,created),
 CHECK (`count` BETWEEN 0 AND 50), CHECK (approved IN (0,1)), CHECK (attending IN ('yes','no','maybe'))
) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE TABLE settings (id TINYINT PRIMARY KEY, value JSON NOT NULL, CHECK (id=1));
CREATE TABLE editor_documents (id TINYINT PRIMARY KEY,draft JSON NOT NULL,published JSON,revision BIGINT NOT NULL DEFAULT 0,updated TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK (id=1));
INSERT INTO editor_documents(id,draft,revision) VALUES(1,JSON_OBJECT(),0);
CREATE TABLE editor_versions(id BIGINT PRIMARY KEY AUTO_INCREMENT,document JSON NOT NULL,created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE editor_presets(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,document JSON NOT NULL,created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE media_assets(id CHAR(36) CHARACTER SET ascii PRIMARY KEY,filename VARCHAR(80) CHARACTER SET ascii UNIQUE NOT NULL,original_name VARCHAR(200) NOT NULL,mime VARCHAR(80) NOT NULL,bytes BIGINT NOT NULL,created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE visit_events(id BIGINT PRIMARY KEY AUTO_INCREMENT,visitor_hash CHAR(64) CHARACTER SET ascii NOT NULL,day DATE NOT NULL,created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX visits_day(day));
CREATE TABLE widget_submissions(id BIGINT PRIMARY KEY AUTO_INCREMENT,widget_id VARCHAR(90) CHARACTER SET ascii NOT NULL,kind VARCHAR(20) NOT NULL,name VARCHAR(100) NOT NULL,phone VARCHAR(30) NOT NULL,email VARCHAR(200) NOT NULL,note TEXT NOT NULL,product VARCHAR(1000) NOT NULL DEFAULT '',quantity INT NOT NULL DEFAULT 0,total BIGINT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'new',submission_key VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin UNIQUE NOT NULL,payload_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX submissions_hash(payload_hash,created));
CREATE TABLE admin_sessions(token_hash CHAR(64) CHARACTER SET ascii PRIMARY KEY,expires TIMESTAMP NOT NULL,created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX sessions_expiry(expires));
CREATE TABLE legacy_imports(source_hash CHAR(64) CHARACTER SET ascii PRIMARY KEY,created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
